INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(3456000, 3456, 0, 1, 0, 0, 0, 0, 'Naxxramas', 'Once an ancient nerubian ziggurat underground. In the War of the Spider, Anub''arak took it for the Lich King, and the Scourge made it a war machine. When Kel''Thuzad came north, Anub''arak led him through its four wings, stacked with plague cauldrons; horrified, Kel''Thuzad tried to flee, but the Lich King caught him and bound him to it. Cultists tore it out of the earth and made it a flying necropolis, and Kel''Thuzad brought it to Lordaeron.\n\nHeroes stormed it once in the Plaguelands and destroyed Kel''Thuzad. Now he has been reborn by the Lich King''s power, and the necropolis has come north, over the Dragonblight.', 'warcraft.wiki.gg: Naxxramas (Road to Damnation, World of Warcraft, Wrath of the Lich King)'),
(3456001, 3456, 1, 1, 0, 0, 0, 0, 'The Arachnid Quarter', 'The wing where the necropolis'' nerubian heritage shows most: webs, crypt lords and spiders, ruled by Anub''Rekhan and the widow Faerlina, with Maexxna at its heart.', 'warcraft.wiki.gg: Naxxramas'),
(3456002, 3456, 1, 2, 0, 0, 0, 0, 'The Plague Quarter', 'Where the plague itself is brewed and studied, under the plaguebringer and the unclean.', 'warcraft.wiki.gg: Naxxramas'),
(3456003, 3456, 1, 3, 0, 0, 0, 0, 'The Military Quarter', 'Where the Scourge trains its death knights, harvests souls, and keeps its four mounted champions, the Horsemen.', 'warcraft.wiki.gg: Naxxramas'),
(3456004, 3456, 1, 4, 0, 0, 0, 0, 'The Construct Quarter', 'The workshops of the abominations, where flesh is stitched together into the Scourge''s monstrosities.', 'warcraft.wiki.gg: Naxxramas'),
(3456005, 3456, 1, 5, 0, 0, 0, 0, 'The Frostwyrm Lair', 'The top of the necropolis, where a frost wyrm guards the way to Kel''Thuzad''s own chamber.', 'warcraft.wiki.gg: Naxxramas'),
(3456030, 3456, 2, 1, 0, 0, 0, 0, 'Anub''Rekhan', 'In life one of the most powerful spider lords of the nerubians; raised by the Lich King as a crypt lord, he guards the doors of the Arachnid Quarter.', 'warcraft.wiki.gg: Anub''Rekhan'),
(3456031, 3456, 2, 2, 0, 0, 0, 0, 'Grand Widow Faerlina', 'Once a high-ranking member of the Cult of the Damned under Kel''Thuzad. In death she tends the endless arachnids swarming from the depths of the citadel. A master of poisons, she knows well what makes mortals suffer; her poisons come from the spiderlings Maexxna bears.', 'warcraft.wiki.gg: Grand Widow Faerlina'),
(3456032, 3456, 2, 3, 0, 0, 0, 0, 'Maexxna', 'A massive spider taken from the depths of Northrend''s mountains ages ago. She breeds her brood in Naxxramas, feeding them on those foolish enough to enter, and Kel''Thuzad uses her spawn to his own foul ends.', 'warcraft.wiki.gg: Maexxna'),
(3456033, 3456, 2, 4, 0, 0, 0, 0, 'Noth the Plaguebringer', 'Once a reputable mage of Dalaran, who heard the Lich King''s call as Kel''Thuzad did and went to serve him. When he saw how many innocents the Third War was killing, he began to doubt. Kel''Thuzad dealt with his growing compassion by freezing the living heart in his chest.', 'warcraft.wiki.gg: Noth the Plaguebringer'),
(3456034, 3456, 2, 5, 0, 0, 0, 0, 'Heigan the Unclean', 'The mastermind behind the cauldrons that spread the plague through Lordaeron, corrupting not only its people but its plants and beasts. That the land is now called the Plaguelands is thanks in no small part to Heigan''s work.', 'warcraft.wiki.gg: Heigan the Unclean'),
(3456035, 3456, 2, 6, 0, 0, 0, 0, 'Loatheb', 'A twisted fen creeper, an example of what the plague does to plants. In a mockery of nature''s power to heal, his spores spread a miasma that turns healing magic against those who use it.', 'warcraft.wiki.gg: Loatheb'),
(3456036, 3456, 2, 7, 0, 0, 0, 0, 'Instructor Razuvious', 'The most feared of the Scourge''s death knight trainers.', 'warcraft.wiki.gg: Instructor Razuvious'),
(3456037, 3456, 2, 8, 0, 0, 0, 0, 'Gothik the Harvester', 'A necromancer who reaps the living and sends their dead back against them.', 'warcraft.wiki.gg: Gothik the Harvester'),
(3456038, 3456, 2, 9, 0, 0, 0, 0, 'The Four Horsemen', 'The Lich King''s death knight champions: Thane Korth''azz, Lady Blaumeux, Sir Zeliek, and Baron Rivendare, once lord of Stratholme.', 'warcraft.wiki.gg: Naxxramas; warcraft.wiki.gg: Baron Rivendare'),
(3456039, 3456, 2, 10, 0, 0, 0, 0, 'The Abominations', 'Patchwerk, one of Kel''Thuzad''s mightiest abominations, terribly fast and strong. Grobbulus, the first successful flesh giant, made to inject the living with plague slime and send them back to infect their allies. Gluth, a plague hound so hungry that the living were not enough; Feugen is said to feed him an army of zombies every day.', 'warcraft.wiki.gg: Patchwerk; warcraft.wiki.gg: Grobbulus; warcraft.wiki.gg: Gluth'),
(3456040, 3456, 2, 11, 0, 0, 0, 0, 'Thaddius', 'A massive abomination pieced together from the flesh of innocent women and children, flanked by two huge wights, Stalagg and Feugen, and supercharged with lightning. The souls bound inside him, it is said, are fused together forever in that foul prison of flesh.', 'warcraft.wiki.gg: Thaddius'),
(3456041, 3456, 2, 12, 0, 0, 0, 0, 'Sapphiron', 'One of the most ancient blue dragons, entrusted by Malygos with a key to the Focusing Iris. He lived with his brood near the entrance to Azjol-Nerub, guarding a hoard of artifacts gathered over centuries, until Arthas killed him and raised him as a frost wyrm to guard Kel''Thuzad''s sanctum.', 'warcraft.wiki.gg: Sapphiron'),
(3456042, 3456, 2, 13, 0, 0, 0, 0, 'Kel''Thuzad', 'A member of the Council of Six of Dalaran who turned to necromancy, answered the Lich King''s call, and founded the Cult of the Damned to spread the plague through Lordaeron. Arthas killed him and later raised him as a lich in the Sunwell. His phylactery let him rise again after the heroes of the Plaguelands destroyed him once already.\n\nHe is the archlich, master of Naxxramas, and the Lich King''s most trusted lieutenant.', 'warcraft.wiki.gg: Kel''Thuzad; warcraft.wiki.gg: Naxxramas');
